from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equal even/odd digits and divisible by k."""

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0

        bound_digits = tuple(map(int, str(bound)))

        def count_length(limits: tuple[int, ...]) -> int:
            length = len(limits)

            @lru_cache(maxsize=None)
            def dp(position: int, balance: int, remainder: int, tight: bool) -> int:
                remaining = length - position
                # Each remaining digit can change the balance by only one.
                if abs(balance) > remaining:
                    return 0
                if position == length:
                    return int(balance == 0 and remainder == 0)

                upper = limits[position] if tight else 9
                lower = 1 if position == 0 else 0
                total = 0
                for digit in range(lower, upper + 1):
                    total += dp(
                        position + 1,
                        balance + (1 if digit % 2 == 0 else -1),
                        (remainder * 10 + digit) % k,
                        tight and digit == limits[position],
                    )
                return total

            return dp(0, 0, 0, True)

        # Equal even/odd digit counts require an even number of digits.
        total = 0
        for length in range(2, len(bound_digits) + 1, 2):
            limits = bound_digits if length == len(bound_digits) else (9,) * length
            total += count_length(limits)
        return total

    return count_up_to(high) - count_up_to(low - 1)

